def localized_report(report,locale):
    d=DATA.get(locale,DATA['en']);fs=report.get('findings',[])
    if not fs:return None
    facts='\n'.join('• “'+x['evidence']+'”' for x in fs)
    risks='\n'.join('• '+d['flags'].get(x['code'],(x['flag'],'Requires verification.'))[1] for x in fs)
    return '**'+d['heading']+'**\n'+facts+'\n\n**'+d['risks']+'**\n'+risks+'\n\n**'+d['unknown']+'**\n'+d['unknown_body']+'\n\n**'+d['checks']+'**\n'+d['checks_body']+'\n\n'+d['note']

def localized_findings(report,locale):
    d=DATA.get(locale,DATA['en']);out=dict(report)
    out['findings']=[dict(f,flag=d['flags'].get(f['code'],(f['flag'],))[0]) for f in report['findings']]
    return out
